"use client";

import React, { useState, useEffect } from "react";
import { motion, useSpring, useTransform } from "motion/react";
import { RotateCcw } from "lucide-react";
import { cn } from "@/lib/utils";

export interface TextFillLoadingProps
  extends React.HTMLAttributes<HTMLDivElement> {
  text?: string;
  autoPlay?: boolean;
}

export function TextFillLoading({
  text = "LOADING",
  autoPlay = true,
  className,
  ...props
}: TextFillLoadingProps) {
  const [progress, setProgress] = useState(0);

  const springProgress = useSpring(progress, {
    stiffness: 80,
    damping: 18,
    mass: 1,
  });

  const clipPath = useTransform(
    springProgress,
    (val) => `inset(0 ${Math.max(0, 100 - val)}% 0 0)`
  );

  useEffect(() => {
    if (!autoPlay) return;
    const interval = setInterval(() => {
      setProgress((prev) => {
        if (prev >= 100) return 0;
        return Math.min(100, prev + Math.floor(Math.random() * 25 + 15));
      });
    }, 800);
    return () => clearInterval(interval);
  }, [autoPlay]);

  return (
    <div
      data-slot="text-fill-loading"
      className={cn(
        "relative flex flex-col items-center justify-center gap-6 select-none p-8",
        className
      )}
      {...props}
    >
      <div className="relative inline-block font-black tracking-tighter text-5xl sm:text-7xl">
        {/* Background ghost layer */}
        <span className="text-pink-500/20 select-none">{text}</span>

        {/* Foreground filled layer clipped by progress */}
        <motion.span
          style={{ clipPath }}
          className="absolute top-0 left-0 text-pink-500 drop-shadow-[0_0_20px_rgba(236,72,153,0.6)] select-none will-change-[clip-path]"
        >
          {text}
        </motion.span>
      </div>

      {/* Progress percentage & Manual controls */}
      <div className="flex items-center gap-4">
        <span className="font-mono text-xs text-neutral-500 font-bold">
          {Math.round(progress)}%
        </span>
        <button
          type="button"
          onClick={() => setProgress((p) => (p >= 100 ? 0 : Math.min(100, p + 25)))}
          className="flex items-center gap-1.5 rounded-full border border-neutral-200 bg-neutral-100 px-3 py-1 text-xs font-semibold text-neutral-800 transition-colors hover:bg-neutral-200 dark:border-neutral-800 dark:bg-neutral-800 dark:text-neutral-200 dark:hover:bg-neutral-700 cursor-pointer"
        >
          <RotateCcw className="h-3 w-3" />
          <span>Step Progress</span>
        </button>
      </div>
    </div>
  );
}
